arquivos_configuracao.conteudo:
# Configuração Central do Dovecot
# Versão: 2.3+

# Serviços ativados
protocols = imap pop3
listen = *, ::

# Diretório de dados dos usuários
mail_location = maildir:~/Maildir
mail_privileged_group = mail
mail_access_groups = mail

# Autenticação contra /etc/passwd e /etc/shadow
auth_mechanisms = plain login
passdb {
  driver = pam
}
userdb {
  driver = passwd
}

# Socket para Postfix SASL
service auth {
  unix_listener /var/spool/postfix/private/auth {
    mode = 0660
    user = postfix
    group = postfix
  }
}

# Configuração de SSL/TLS
ssl = required
ssl_cert = </etc/letsencrypt/live/seu-dominio.com/fullchain.pem
ssl_key = </etc/letsencrypt/live/seu-dominio.com/privkey.pem
ssl_min_protocol = TLSv1.2
ssl_cipher_list = HIGH:!aNULL:!MD5

# IMAP (portas 143 e 993)
service imap-login {
  inet_listener imap {
    port = 143
  }
  inet_listener imaps {
    port = 993
    ssl = yes
  }
}

# POP3 (portas 110 e 995)
service pop3-login {
  inet_listener pop3 {
    port = 110
  }
  inet_listener pop3s {
    port = 995
    ssl = yes
  }
}

# Limites de conexão
default_process_limit = 100
default_client_limit = 2048

# Replicação e failover (opcional para alta disponibilidade)
# dsync_remote_cmd = ssh -l%{login} %{host} doveadm dsync-server -u %{user}

# Logs
log_path = /var/log/dovecot.log
info_log_path = /var/log/dovecot-info.log
